    internal static void Register(StoryCatalogBuilder builder, IReadOnlyList<GeneratedComponentStoryDescriptor> descriptors)
    {
        ArgumentNullException.ThrowIfNull(builder);
        Dictionary<string, GeneratedComponentStoryDescriptor> byType = descriptors.ToDictionary(static item => item.ComponentType, StringComparer.Ordinal);
        foreach (Page page in Pages)
        {
            string identity = $"global::Luxel.Controls.{page.Type}";
            if (page.Type == "DiagramBlock") identity = "global::Luxel.Diagram.DiagramBlock";
            if (page.Type == "MathBlockView") identity = "global::Luxel.MathText.MathBlockView";
            if (!byType.TryGetValue(identity, out GeneratedComponentStoryDescriptor? descriptor))
                throw new InvalidOperationException($"Docs 対象のコンポーネントが見つかりません: {identity}");
            builder.Add(new StoryInfo(descriptor.DocsPath, _ => Build(page, descriptor), Source: "日本語で執筆したコンポーネント Docs。"), replaceGenerated: true);
        }
    }

    private static StoryResult Build(Page page, GeneratedComponentStoryDescriptor descriptor)
    {
        var result = new StoryResult(1400, 1);
        result.AppendLiteral($"# {page.Title}\n\n## 概要と用途\n\n{page.Overview}\n\n## 最小使用例\n\n```csharp\n{page.Usage}\n```\n\n## 状態の所有\n\n{page.State}\n\n## 主なパラメーターとイベント\n\n{page.MainApi}\n\n## 操作・キーボード・アクセシビリティ\n\n{page.Operations}\n\n## テーマとレイアウト\n\n{page.Theme}\n\n## 制約・能力・ライフサイクル\n\n{page.Limits}\n\n## API リファレンス\n\n");
        result.AppendFormatted(new DocEmbed(global::Luxel.Gallery.UI.Kit.ApiTable(page.Api, inherited: true, width: 760), DocEmbedKind.ControlApiTable, page.Api, IncludeInherited: true));
        result.AppendLiteral($"\n\n## 関連する Basic と Examples\n\n- [Basic](story:{descriptor.BasicPath})\n");
        foreach (string example in page.Examples ?? []) result.AppendLiteral($"- [{example[(example.LastIndexOf('/') + 1)..]}](story:{example})\n");
        return result;
    }

    private static Page P(string type, string title, string overview, string usage, string state, string mainApi,
        string operations, string theme, string limits, string api, string[]? examples = null)
        => new(type, title, overview, usage, state, mainApi, operations, theme, limits, api, examples);
}
